selector_to_html = {"a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"ducts/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts<a class=\"headerlink\" href=\"#module-pyskyfire.ducts\" title=\"Link to this heading\">\u00b6</a></h1><p>Duct hydraulics shared by cooling channels, piping and manifolds.</p><p>This subpackage contains shared path geometry, explicit pipe hydraulics,\nannular ducts, orifices and orifice plates, and volute and collector manifolds. It depends only on <a class=\"reference internal\" href=\"common/index.html#module-pyskyfire.common\" title=\"pyskyfire.common\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.common</span></code></a> for\nplanar section primitives and friction correlations and <a class=\"reference internal\" href=\"thermo/index.html#module-pyskyfire.thermo\" title=\"pyskyfire.thermo\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.thermo</span></code></a> for fluid state records,\nand it does not import from <a class=\"reference internal\" href=\"regen/index.html#module-pyskyfire.regen\" title=\"pyskyfire.regen\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen</span></code></a> or <a class=\"reference internal\" href=\"network/index.html#module-pyskyfire.network\" title=\"pyskyfire.network\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.network</span></code></a>,\nso cooling channels, turbopump hardware and engine-network adapters can all\ndepend on it without a cycle.</p>", "a[href=\"heat_exchanger/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.heat_exchanger<a class=\"headerlink\" href=\"#module-pyskyfire.heat_exchanger\" title=\"Link to this heading\">\u00b6</a></h1><p>Path-based heat exchangers with prescribed gas or coupled fluid circuits.</p>", "a[href=\"viz/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"_dev_commands/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire._dev_commands<a class=\"headerlink\" href=\"#module-pyskyfire._dev_commands\" title=\"Link to this heading\">\u00b6</a></h1><p>Console entry points for repository development commands.</p>", "a[href=\"#module-pyskyfire\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire<a class=\"headerlink\" href=\"#module-pyskyfire\" title=\"Link to this heading\">\u00b6</a></h1><p>pyskyfire - A Python library for rocket engine simulation and design.</p>", "a[href=\"thermo/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo<a class=\"headerlink\" href=\"#module-pyskyfire.thermo\" title=\"Link to this heading\">\u00b6</a></h1><p>Fluid properties, thermodynamic states and combustion-gas aerothermodynamics.</p><p>CEA-backed APIs are loaded on first access so fluid and nozzle-loss utilities\ncan be imported without loading CEA, including through the package root.</p>", "a[href=\"turbine/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.turbine<a class=\"headerlink\" href=\"#module-pyskyfire.turbine\" title=\"Link to this heading\">\u00b6</a></h1><p>Axial turbine design: the duty, a meanline design, and the hardware it produces.</p>", "a[href=\"pump/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump<a class=\"headerlink\" href=\"#module-pyskyfire.pump\" title=\"Link to this heading\">\u00b6</a></h1><p>Preliminary centrifugal pump design with optional pyTurbo blade generation.</p>", "a[href=\"injector/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.injector<a class=\"headerlink\" href=\"#module-pyskyfire.injector\" title=\"Link to this heading\">\u00b6</a></h1><p>Injectors: element sets on a face, and the flow from each feed through them.</p><p>Each element type is its own class. <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ImpingingElement</span></code> is the first:\njets aimed at a common point, which covers like and unlike doublets, triplets\nand pentads. Holes are <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Orifice</span></code> objects, so sizing,\ndischarge coefficients, choking and cavitation come from <a class=\"reference internal\" href=\"ducts/index.html#module-pyskyfire.ducts\" title=\"pyskyfire.ducts\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts</span></code></a>.\nThis subpackage depends on <a class=\"reference internal\" href=\"ducts/index.html#module-pyskyfire.ducts\" title=\"pyskyfire.ducts\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts</span></code></a> and <a class=\"reference internal\" href=\"thermo/index.html#module-pyskyfire.thermo\" title=\"pyskyfire.thermo\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.thermo</span></code></a>\nonly; the engine network adapts it through\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">InjectorBlock</span></code>.</p>", "a[href=\"common/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common<a class=\"headerlink\" href=\"#module-pyskyfire.common\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"network/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.network<a class=\"headerlink\" href=\"#module-pyskyfire.network\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"regen/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen<a class=\"headerlink\" href=\"#module-pyskyfire.regen\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
